static int fw(const void *d, size_t n, void *ctx)
{ return fwrite(d, 1, n, (FILE *)ctx) == n ? 0 : -1; }

int main(void)
{
    static ark_wb_t wb;
    FILE *f = fopen("gen_zhixin.xlsx", "wb");
    if (!f) return 1;
    ark_wb_init(&wb, fw, f);
    build(&wb);
    ark_err_t e = ark_wb_save(&wb);
    fclose(f);
    printf("save: %d\n", (int)e);
    return e != 0;
}
